/**
 * Regenerates the expected outputs in `conformance/` from the TypeScript implementation.
 * Hand-written cases (entries with a `published` field in `stats.json`) are kept as they are.
 *
 *   npm run conformance:generate
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import {
  agreementInputs,
  CONFORMANCE,
  cliInputs,
  computeAgreement,
  computeCalibration,
  computeCli,
  computeEvalrun,
  computeGolden,
  computeRules,
  computeStats,
  goldenInputs,
} from "./conformance";

const NOTE =
  "Generated by typescript/scripts/conformance-generate.ts from the TypeScript implementation. Do not edit by hand; entries with a 'published' field are hand-written and kept.";

async function write(name: string, value: unknown): Promise<void> {
  const path = join(CONFORMANCE, name);
  await mkdir(join(path, ".."), { recursive: true });
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

type Section = Array<Record<string, unknown>>;

const existing = JSON.parse(await readFile(join(CONFORMANCE, "stats.json"), "utf8")) as Record<
  string,
  unknown
>;
const generated = computeStats();
const stats: Record<string, unknown> = { $comment: NOTE };
for (const [key, cases] of Object.entries(generated)) {
  const kept = ((existing[key] as Section | undefined) ?? []).filter(
    (entry) => "published" in entry,
  );
  stats[key] = [...kept, ...cases];
}
await write("stats.json", stats);

const agreement = [];
for (const c of await agreementInputs()) agreement.push({ ...c, expected: computeAgreement(c) });
await write("agreement.json", { $comment: NOTE, cases: agreement });

await write("rules.json", { $comment: NOTE, ...computeRules() });

const golden = [];
for (const c of await goldenInputs()) golden.push({ ...c, expected: computeGolden(c) });
await write("golden.json", { $comment: NOTE, cases: golden });

await write("evalrun.json", { $comment: NOTE, ...(await computeEvalrun()) });
await write("calibration.json", { $comment: NOTE, ...(await computeCalibration()) });

const cli = [];
for (const c of cliInputs()) {
  const { exit, stdout } = await computeCli(c.args);
  cli.push({ ...c, cwd: "conformance/data (a fresh copy per case)", exit, stdout });
}
await write("cli/cases.json", { $comment: NOTE, cases: cli });

console.log(
  `wrote stats, agreement (${agreement.length}), rules, golden (${golden.length}), evalrun, calibration and ${cli.length} CLI cases`,
);
